"""Validate files generated by risk_export_browser_test.cjs, including cell fills."""
import json
import re
import zipfile
from decimal import Decimal
from pathlib import Path
from xml.etree import ElementTree as ET

import fitz

directory = Path(__file__).resolve().parents[1] / '.local/risk-export-review'
ns = {'s': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
palette = {'E7F1FF', 'E9F8ED', 'FFF7CC', 'FFF0DC', 'FDE7E7'}


def value(cell):
    if cell.get('t') == 'inlineStr':
        return ''.join(cell.itertext())
    return cell.findtext('s:v', '', ns)


for name in ['hasil-kc-all', 'hasil-kc-ops', 'rekap-korwil-solo']:
    expected = json.loads((directory / (name + '.expected.json')).read_text())
    with zipfile.ZipFile(directory / (name + '.xlsx')) as package:
        assert package.testzip() is None
        # Every XML part must be well-formed, including styles and relationships.
        for entry in package.namelist():
            if entry.endswith(('.xml', '.rels')):
                ET.fromstring(package.read(entry))
        sheet = ET.fromstring(package.read('xl/worksheets/sheet1.xml'))
        styles = ET.fromstring(package.read('xl/styles.xml'))
        rows = sheet.findall('s:sheetData/s:row', ns)
        header_index = next(i for i, row in enumerate(rows)
                            if [value(cell).strip() for cell in row] == expected['headers'])
        xfs = styles.find('s:cellXfs', ns)
        fills = styles.find('s:fills', ns)
        assert len(xfs) == int(xfs.get('count'))
        assert len(fills) == int(fills.get('count'))
        coloured = 0
        for index, wanted_row in enumerate(expected['rows']):
            cells = list(rows[header_index + 1 + index])
            assert len(cells) == len(wanted_row), 'Missing visible column'
            for column, (cell, wanted) in enumerate(zip(cells, wanted_row)):
                actual = value(cell).strip()
                if column != 1 and re.fullmatch(r'-?\d+(?:\.\d+)?', wanted['text']):
                    assert Decimal(actual) == Decimal(wanted['text'])
                else:
                    assert actual == wanted['text'], (name, index, column, actual, wanted['text'])
                xf = xfs[int(cell.get('s', '0'))]
                fill = fills[int(xf.get('fillId', '0'))].find('s:patternFill/s:fgColor', ns)
                colour = fill.get('rgb', '')[-6:].upper() if fill is not None else ''
                if wanted['bg']:
                    rgb = re.findall(r'\d+', wanted['bg'])[:3]
                    assert colour == ''.join(f'{int(part):02X}' for part in rgb), 'Excel colour differs from web'
                    coloured += 1
                else:
                    assert colour not in palette, 'Non-rating/missing cell received a rating colour'
        assert coloured > 0
        text = ' '.join(sheet.itertext())
        assert 'Keterangan warna berdasarkan peringkat' in text
        for label in ['Sangat rendah', 'Rendah', 'Sedang', 'Tinggi', 'Sangat tinggi']:
            assert label in text
        # The legend must not overlap existing merged title/metadata rows.
        occupied = set()
        for merge in sheet.findall('s:mergeCells/s:mergeCell', ns):
            first, last = merge.get('ref').split(':')
            def address(token):
                letters, row = re.fullmatch(r'([A-Z]+)(\d+)', token).groups()
                column = 0
                for char in letters:
                    column = column * 26 + ord(char) - 64
                return column, int(row)
            x1, y1 = address(first); x2, y2 = address(last)
            for y in range(y1, y2 + 1):
                for x in range(x1, x2 + 1):
                    assert (x, y) not in occupied, 'Overlapping Excel legend merge'
                    occupied.add((x, y))
    with fitz.open(directory / (name + '.pdf')) as document:
        text = ' '.join(page.get_text() for page in document)
        assert 'Keterangan warna berdasarkan peringkat' in text
        assert 'Komposit:' in text and 'Pilar/inheren:' in text
        compact = re.sub(r'\s+', '', text)
        assert all(re.sub(r'\s+', '', header) in compact for header in expected['headers']), 'PDF dropped a visible column'
        colours = set()
        for page in document:
            for drawing in page.get_drawings():
                if drawing['fill']:
                    colours.add(''.join(f'{round(channel * 255):02X}' for channel in drawing['fill']))
            for x0, y0, x1, y1, *_ in page.get_text('words'):
                assert x0 >= -1 and y0 >= -1 and x1 <= page.rect.width + 1 and y1 <= page.rect.height + 1, 'PDF content outside paper'
        assert palette <= colours, 'PDF legend colour missing'
        document[0].get_pixmap(matrix=fitz.Matrix(1, 1)).save(directory / (name + '.png'))
    print(f'PASS {name}: values, row order, Excel colour per cell, legend merges, PDF palette and page bounds')
